import type { Vec3 } from '../contracts/math';

export interface BoxZone { shape: 'box'; center: Vec3; halfExtents: Vec3; }
export interface SphereZone { shape: 'sphere'; center: Vec3; radius: number; }
export type TriggerZone = BoxZone | SphereZone;

interface BaseConfig { id: string; zone: TriggerZone; enabled?: boolean; }
interface CooldownConfig extends BaseConfig { cooldownSeconds?: number; }
export interface BumperConfig extends CooldownConfig { type: 'bumper'; normal: Vec3; impulse: number; }
export interface SpringPadConfig extends CooldownConfig { type: 'spring-pad'; impulse: number; }
export interface BoostPadConfig extends CooldownConfig { type: 'boost-pad'; direction: Vec3; impulse: number; maxSpeed?: number; }
export interface JumpPadConfig extends CooldownConfig { type: 'jump-pad'; verticalImpulse: number; forwardDirection?: Vec3; forwardImpulse?: number; }
export interface TeleporterConfig extends CooldownConfig { type: 'teleporter'; destination: Vec3; exitVelocity?: Vec3; preserveVelocity?: boolean; }
export interface FanConfig extends BaseConfig { type: 'fan'; direction: Vec3; acceleration: number; maxSpeed?: number; }
export interface ConveyorConfig extends BaseConfig { type: 'conveyor'; direction: Vec3; acceleration: number; maxSpeed?: number; }
export interface IceSurfaceConfig extends BaseConfig { type: 'ice-surface'; friction: number; restitution?: number; }
export interface MudSurfaceConfig extends BaseConfig { type: 'mud-surface'; friction: number; velocityDamping: number; }
export interface WaterZoneConfig extends CooldownConfig { type: 'water-zone'; penaltyStrokes?: number; resetPosition?: Vec3; }
export interface LavaZoneConfig extends CooldownConfig { type: 'lava-zone'; penaltyStrokes?: number; resetPosition?: Vec3; }
export interface KillZoneConfig extends CooldownConfig { type: 'kill-zone'; penaltyStrokes?: number; resetPosition?: Vec3; }
export interface GravityZoneConfig extends BaseConfig { type: 'gravity-zone'; acceleration: Vec3; }
export interface MagnetZoneConfig extends BaseConfig { type: 'magnet-zone'; target: Vec3; strength: number; maxAcceleration?: number; }

export type TriggerConfig = BumperConfig | SpringPadConfig | BoostPadConfig | JumpPadConfig | TeleporterConfig | FanConfig | ConveyorConfig | IceSurfaceConfig | MudSurfaceConfig | WaterZoneConfig | LavaZoneConfig | KillZoneConfig | GravityZoneConfig | MagnetZoneConfig;

export interface BallTriggerState { position: Vec3; velocity: Vec3; }
export interface TriggerEffect { velocity?: Vec3; position?: Vec3; friction?: number; restitution?: number; penaltyStrokes?: number; reset?: boolean; }
