import type { Vec3 } from '../contracts/math';
import type { TriggerZone } from './types';

export const add = (a: Vec3, b: Vec3): Vec3 => ({ x:a.x+b.x, y:a.y+b.y, z:a.z+b.z });
export const scale = (v: Vec3, s: number): Vec3 => ({ x:v.x*s, y:v.y*s, z:v.z*s });
export const length = (v: Vec3): number => Math.hypot(v.x,v.y,v.z);
export const normalize = (v: Vec3): Vec3 => { const n=length(v); return n > 1e-9 ? scale(v,1/n) : {x:0,y:0,z:0}; };
export const cap = (v: Vec3, max?: number): Vec3 => !max || length(v)<=max ? v : scale(normalize(v),max);
export function contains(zone: TriggerZone, p: Vec3): boolean {
  if(zone.shape==='sphere') return Math.hypot(p.x-zone.center.x,p.y-zone.center.y,p.z-zone.center.z)<=zone.radius;
  return Math.abs(p.x-zone.center.x)<=zone.halfExtents.x && Math.abs(p.y-zone.center.y)<=zone.halfExtents.y && Math.abs(p.z-zone.center.z)<=zone.halfExtents.z;
}
