import type { Vec3 } from '../contracts/math';
import { add, cap, normalize, scale } from './TriggerMath';
import type { BallTriggerState, TriggerConfig, TriggerEffect } from './types';

const accelerated = (velocity:Vec3, direction:Vec3, acceleration:number, dt:number, maxSpeed?:number) => cap(add(velocity,scale(normalize(direction),acceleration*dt)),maxSpeed);
export function resolveTriggerEffect(config: TriggerConfig, ball: BallTriggerState, dt=1/60): TriggerEffect {
 switch(config.type){
  case 'bumper': return {velocity:add(ball.velocity,scale(normalize(config.normal),config.impulse))};
  case 'spring-pad': return {velocity:add(ball.velocity,{x:0,y:config.impulse,z:0})};
  case 'boost-pad': return {velocity:cap(add(ball.velocity,scale(normalize(config.direction),config.impulse)),config.maxSpeed)};
  case 'jump-pad': return {velocity:add(ball.velocity,add({x:0,y:config.verticalImpulse,z:0},scale(normalize(config.forwardDirection??{x:0,y:0,z:0}),config.forwardImpulse??0)))};
  case 'teleporter': return {position:{...config.destination},velocity:config.exitVelocity?{...config.exitVelocity}:config.preserveVelocity===false?{x:0,y:0,z:0}:{...ball.velocity}};
  case 'fan': return {velocity:accelerated(ball.velocity,config.direction,config.acceleration,dt,config.maxSpeed)};
  case 'conveyor': return {velocity:accelerated(ball.velocity,config.direction,config.acceleration,dt,config.maxSpeed)};
  case 'ice-surface': return {friction:config.friction,restitution:config.restitution};
  case 'mud-surface': return {friction:config.friction,velocity:scale(ball.velocity,Math.max(0,1-config.velocityDamping*dt))};
  case 'water-zone': case 'lava-zone': case 'kill-zone': return {position:config.resetPosition?{...config.resetPosition}:undefined,velocity:{x:0,y:0,z:0},penaltyStrokes:config.penaltyStrokes??1,reset:true};
  case 'gravity-zone': return {velocity:add(ball.velocity,scale(config.acceleration,dt))};
  case 'magnet-zone': { const delta={x:config.target.x-ball.position.x,y:config.target.y-ball.position.y,z:config.target.z-ball.position.z}; const accel=Math.min(config.strength,config.maxAcceleration??Infinity); return {velocity:add(ball.velocity,scale(normalize(delta),accel*dt))}; }
 }
}
