import type { Vec3 } from '../contracts/math';
import { contains } from './TriggerMath';
import { resolveTriggerEffect } from './TriggerEffects';
import type { BallTriggerState, TriggerConfig, TriggerEffect } from './types';

export interface TriggerBallAdapter {
 getState(): BallTriggerState;
 setVelocity(v:Vec3): void;
 setPosition(v:Vec3): void;
 setSurface?(friction:number,restitution?:number): void;
 addPenalty?(strokes:number): void;
}
const impulseTypes=new Set(['bumper','spring-pad','boost-pad','jump-pad','teleporter','water-zone','lava-zone','kill-zone']);
export class TriggerSystem {
 private readonly inside=new Set<string>(); private readonly lastFire=new Map<string,number>();
 constructor(public readonly configs: readonly TriggerConfig[]){}
 update(ball:TriggerBallAdapter,dt:number,nowSeconds:number): TriggerEffect[] {
  const effects:TriggerEffect[]=[]; const state=ball.getState();
  for(const c of this.configs){
   if(c.enabled===false) continue; const hit=contains(c.zone,state.position); const was=this.inside.has(c.id);
   if(!hit){this.inside.delete(c.id);continue;} this.inside.add(c.id);
   if(impulseTypes.has(c.type)){
    const cooldown='cooldownSeconds' in c ? c.cooldownSeconds??0 : 0; const last=this.lastFire.get(c.id)??-Infinity;
    if(was || nowSeconds-last<cooldown) continue; this.lastFire.set(c.id,nowSeconds);
   }
   const effect=resolveTriggerEffect(c,ball.getState(),dt); effects.push(effect); this.apply(ball,effect);
  }
  return effects;
 }
 reset():void { this.inside.clear(); this.lastFire.clear(); }
 private apply(ball:TriggerBallAdapter,e:TriggerEffect):void { if(e.position) ball.setPosition(e.position); if(e.velocity) ball.setVelocity(e.velocity); if(e.friction!==undefined) ball.setSurface?.(e.friction,e.restitution); if(e.penaltyStrokes) ball.addPenalty?.(e.penaltyStrokes); }
}
