import { describe, expect, it } from 'vitest';
import type { Vec3 } from '../contracts/math';
import { TriggerSystem } from './TriggerSystem';
import { resolveTriggerEffect } from './TriggerEffects';
import { contains } from './TriggerMath';
import type { BallTriggerState, TriggerConfig } from './types';

const box={shape:'box' as const,center:{x:0,y:0,z:0},halfExtents:{x:1,y:1,z:1}};
class Ball { state:BallTriggerState={position:{x:0,y:0,z:0},velocity:{x:0,y:0,z:0}}; penalties=0; surface?:number; getState(){return this.state;} setVelocity(v:Vec3){this.state={...this.state,velocity:v};} setPosition(v:Vec3){this.state={...this.state,position:v};} setSurface(f:number){this.surface=f;} addPenalty(n:number){this.penalties+=n;} }
describe('trigger geometry and entry semantics',()=>{
 it('detects box and sphere membership',()=>{expect(contains(box,{x:1,y:0,z:0})).toBe(true);expect(contains(box,{x:1.1,y:0,z:0})).toBe(false);expect(contains({shape:'sphere',center:{x:0,y:0,z:0},radius:2},{x:0,y:0,z:2})).toBe(true);});
 it('fires an impulse trigger once per entry',()=>{const c:TriggerConfig={id:'b',type:'spring-pad',zone:box,impulse:4};const b=new Ball();const s=new TriggerSystem([c]);expect(s.update(b,1/60,0)).toHaveLength(1);expect(s.update(b,1/60,.1)).toHaveLength(0);b.state.position={x:2,y:0,z:0};s.update(b,1/60,.2);b.state.position={x:0,y:0,z:0};expect(s.update(b,1/60,.3)).toHaveLength(1);expect(b.state.velocity.y).toBe(8);});
 it('honors cooldown across re-entry',()=>{const c:TriggerConfig={id:'j',type:'jump-pad',zone:box,verticalImpulse:3,cooldownSeconds:1};const b=new Ball();const s=new TriggerSystem([c]);s.update(b,.016,0);b.state.position={x:2,y:0,z:0};s.update(b,.016,.1);b.state.position={x:0,y:0,z:0};expect(s.update(b,.016,.5)).toHaveLength(0);});
});
describe('force and surface effects',()=>{
 it('boosts in normalized direction and caps speed',()=>{const e=resolveTriggerEffect({id:'x',type:'boost-pad',zone:box,direction:{x:10,y:0,z:0},impulse:20,maxSpeed:12},{position:{x:0,y:0,z:0},velocity:{x:1,y:0,z:0}});expect(e.velocity?.x).toBeCloseTo(12);});
 it('applies fan, conveyor, gravity and magnet forces by dt',()=>{const ball={position:{x:0,y:0,z:0},velocity:{x:0,y:0,z:0}};expect(resolveTriggerEffect({id:'f',type:'fan',zone:box,direction:{x:1,y:0,z:0},acceleration:6},ball,.5).velocity?.x).toBeCloseTo(3);expect(resolveTriggerEffect({id:'c',type:'conveyor',zone:box,direction:{x:0,y:0,z:1},acceleration:4},ball,.5).velocity?.z).toBeCloseTo(2);expect(resolveTriggerEffect({id:'g',type:'gravity-zone',zone:box,acceleration:{x:0,y:8,z:0}},ball,.25).velocity?.y).toBeCloseTo(2);expect(resolveTriggerEffect({id:'m',type:'magnet-zone',zone:box,target:{x:10,y:0,z:0},strength:10,maxAcceleration:4},ball,.5).velocity?.x).toBeCloseTo(2);});
 it('models ice and mud surfaces',()=>{expect(resolveTriggerEffect({id:'i',type:'ice-surface',zone:box,friction:.02}, {position:{x:0,y:0,z:0},velocity:{x:4,y:0,z:0}}).friction).toBe(.02);expect(resolveTriggerEffect({id:'m',type:'mud-surface',zone:box,friction:1.5,velocityDamping:2},{position:{x:0,y:0,z:0},velocity:{x:4,y:0,z:0}},.25).velocity?.x).toBeCloseTo(2);});
});
describe('teleport and hazards',()=>{
 it('teleports while preserving velocity by default',()=>{const e=resolveTriggerEffect({id:'t',type:'teleporter',zone:box,destination:{x:8,y:2,z:-3}},{position:{x:0,y:0,z:0},velocity:{x:2,y:1,z:4}});expect(e.position).toEqual({x:8,y:2,z:-3});expect(e.velocity).toEqual({x:2,y:1,z:4});});
 it('supports explicit teleporter exit velocity',()=>{const e=resolveTriggerEffect({id:'t',type:'teleporter',zone:box,destination:{x:8,y:0,z:0},exitVelocity:{x:0,y:2,z:5}},{position:{x:0,y:0,z:0},velocity:{x:9,y:0,z:0}});expect(e.velocity).toEqual({x:0,y:2,z:5});});
 it.each(['water-zone','lava-zone','kill-zone'] as const)('%s resets and penalizes',type=>{const b=new Ball();b.state.velocity={x:5,y:0,z:0};const s=new TriggerSystem([{id:type,type,zone:box,penaltyStrokes:2,resetPosition:{x:3,y:1,z:4}}]);s.update(b,.016,0);expect(b.state.position).toEqual({x:3,y:1,z:4});expect(b.state.velocity).toEqual({x:0,y:0,z:0});expect(b.penalties).toBe(2);});
});
